                State := 3;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            ELSE
                State := 2;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
        3:
            IF T#3s <= PT_REACT THEN
                State := 4;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSE
                State := 3;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
        4:
            IF Level <= LVL_LOW THEN
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSE
                State := 4;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := TRUE;
            END_IF;
    END_CASE;
END_IF;

IF State = 1 THEN
    FillValve := TRUE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF State = 2 THEN
    FillValve := FALSE;
    Heater := TRUE;
    Agitator := TRUE;
    DrainValve := FALSE;
ELSIF State = 3 THEN
    FillValve := FALSE;
    Heater := TRUE;
    Agitator := TRUE;
    DrainValve := FALSE;
ELSIF State = 4 THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := TRUE;
ELSE
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

