    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
    T1 : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND State = 0 THEN
    State := 1;
ELSIF State = 1 AND Level >= 80 THEN
    State := 2;
ELSIF State = 2 AND Temp >= 100 THEN
    State := 3;
ELSIF State = 3 AND T1.Q THEN
    State := 4;
ELSIF State = 4 AND Level <= 5 THEN
    State := 0;
END_IF;

CASE State OF
    0:  // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    1:  // Fill
        FillValve := Level < 80;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    2:  // Heat
        FillValve := FALSE;
        Heater := Temp < 100;
        Agitator := Temp < 100;
        DrainValve := FALSE;
        T1(IN := TRUE, PT := T#3s);
    3:  // React
        FillValve := FALSE;
        Heater := Temp < 100;
        Agitator := Temp < 100;
        DrainValve := FALSE;
    4:  // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := Level > 5;
END_CASE;

IF NOT (FillValve AND DrainValve) AND Level >= 10 AND NOT EStop THEN
    Heater := Heater;
    Agitator := Agitator;
ELSE
    Heater := FALSE;
    Agitator := FALSE;
END_IF;
END_PROGRAM

