        3:
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
            IF T1.Q THEN
                T1(IN := TRUE, PT := PT_REACT);
                State := 4;
            END_IF;
        4:
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

IF FillValve AND DrainValve OR Level < LIQ_MIN THEN
