    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR

CASE State OF
    0: -- Idle
        IF EStop THEN
            State := 0;
        ELSIF StartCycle AND Level < 90 THEN
            State := 1;
        ELSE
            State := 0;
        END_IF;
        Pump := FALSE;
        Valve := FALSE;

    1: -- Filling
        IF EStop OR Level >= 90 THEN
            State := 0;
        ELSE
            State := 1;
        END_IF;
        Pump := TRUE;
        Valve := FALSE;

    2: -- Draining
        IF EStop OR Level <= 10 THEN
            State := 0;
        ELSE
            State := 2;
        END_IF;
        Pump := FALSE;
        Valve := TRUE;
END_CASE;

END_PROGRAM

