    Flame : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR
VAR
    State : INT := 0;
    PurgeTimer : TON;
    IgnitionTimer : TON;
END_VAR

CASE State OF
    0: // Off
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;

    1: // Pre-purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        PurgeTimer(IN := TRUE, PT := T#3s);
        IF NOT PurgeTimer.Q OR NOT EStop THEN
            State := 0;
        ELSIF PurgeTimer.Q THEN
            State := 2;
        END_IF;

    2: // Ignition trial
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IgnitionTimer(IN := TRUE, PT := T#2s);
        IF Flame THEN
            State := 3;
        ELSIF NOT EStop OR StopPB THEN
            State := 0;
        ELSIF NOT IgnitionTimer.Q THEN
            State := 0;
        END_IF;

    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR Not EStop OR StopPB THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR
VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR
VAR
    State : INT := 0;
END_VAR

CASE State OF
    0: // Off
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;
    1: // Purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF NOT EStop OR StopPB THEN
            State := 0;
        ELSIF T1.Q THEN
            State := 2;
        END_IF;
        T1(IN := TRUE, PT := PT_PURGE);
    2: // Ignite
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF NOT EStop OR StopPB THEN
            State := 0;
        ELSIF T2.Q AND Flame THEN
            State := 3;
        END_IF;
        T2(IN := TRUE, PT := PT_IGN);
    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT EStop OR StopPB OR NOT Flame THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

