CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
        IF EStop = FALSE OR StopPB THEN
            State := 0;
        ELSIF StartPB AND EStop THEN
            State := 1;
        END_IF;

    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
        IF EStop = FALSE OR StopPB THEN
            State := 0;
        ELSIF StartPB AND EStop AND NOT C2 THEN
            State := 2;
        END_IF;

    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
        IF EStop = FALSE OR StopPB THEN
            State := 0;
        ELSIF StartPB AND EStop AND NOT C3 THEN
            State := 3;
        END_IF;

    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
        IF EStop = FALSE OR StopPB THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
