    T2 : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
ELSIF StartPB AND NOT StopPB THEN
    CASE State OF
        0:
            IF T2.Q THEN
