            IF SeqTimer2.Q THEN
                State := 3;
            END_IF;
        3:
            IF NOT StopPB THEN
                State := 3;
            ELSE
                State := 2;
            END_IF;
    END_CASE;
ELSE
    State := 0;
END_IF;

